async (page) => {
  const fs = require('fs');
  const path = require('path');

  // Function to get directory size recursively
  function getDirSize(dirPath) {
    let size = 0;
    try {
      const files = fs.readdirSync(dirPath);
      for (const file of files) {
        const filePath = path.join(dirPath, file);
        const stat = fs.statSync(filePath);
        if (stat.isDirectory()) {
          size += getDirSize(filePath);
        } else {
          size += stat.size;
        }
      }
    } catch (err) {
      // Skip if can't read
    }
    return size;
  }

  // Get all subdirectories
  const baseDir = '/tmp/mcp-workspace';
  const dirs = fs.readdirSync(baseDir).filter(f => {
    const stat = fs.statSync(path.join(baseDir, f));
    return stat.isDirectory();
  });

  // Calculate sizes
  const dirSizes = dirs.map(dir => ({
    name: dir,
    size: getDirSize(path.join(baseDir, dir))
  }));

  // Sort by size descending
  dirSizes.sort((a, b) => b.size - a.size);

  return dirSizes.slice(0, 10);
}

